  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }

  public getData() {

    this.isLoading = true;

    switch (this.searchIdValue) {
      case '1':
        this.getCoursePay();
        break;
      case '2':
        this.getWalletCharge();
        break;
      case '3':
        this.getExamPay();
        break;
      case '4':
        this.getCoursePay2();
        break;
      case '5':
        this.getWalletCharge2();
        break;
      case '6':
        this.getExamPay2();
        break;
      case '7':
        this.getAgainPay();
        break;
      case '8':
        this.getAgainPay2();
        break;
      case '9':
        this.getCoursePay3();
        break;
      case '10':
        this.getWalletCharge3();
        break;
      case '11':
        this.getExamPay3();
        break;
      case '12':
        this.getAgainPay3();
        break;
      case '13':
        this.setQueryParams2(1, -1, 23);
        break;
      case '14':
        this.setQueryParams2(1, 9, 23);
        break;
      case '15':
        this.setQueryParams2(1, 10, 23);
        break;
      case '16':
        this.setQueryParams3(1, 7, 23);
        break;
      case '17':
        this.setQueryParams3(1, 6, 23);
        break;
      case '18':
        this.setQueryParams3(1, 8, 23);
        break;
      case '19':
        this.setQueryParams3(1, 9, 23);
        break;
      case '20':
        this.setQueryParams3(1, 9, 24);
        break;
      case '21':
        this.getCoursePay4();
        break;

      default:
        SharedIonic.unSuccessToast(this.toastController);
        break;
    }
  }

  async presentAddWalletAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onAddWallet();
          }
        }
      ]
    });

    await alert.present();
  }

  onAddWallet() {

    if (this.walletForm.valid) {

      SharedIonic.loading(this.loadingController);

      this.userService.AdminAddAllWallet(
        +this.walletForm.value.cash
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

